<script lang="ts">
 import {imageDates} from './imagery.mjs';
 import CropDashboard from './CropDashboard.svelte';
 import OperationsDashboard from './OperationsDashboard.svelte';
 import ProviderInventory from './ProviderInventory.svelte';
 import JobHealth from './JobHealth.svelte';
 import FieldChanges from './FieldChanges.svelte';
 import AlertCenter from './AlertCenter.svelte';
 import HistoryRequests from './HistoryRequests.svelte';
 import DatePicker from './DatePicker.svelte';
 import {untrack} from 'svelte';
 import {todayISO} from './calendar.mjs';
 import {enhance} from '$app/forms';
 import {feedbackForm} from '#lib/feedback.ts';
 import ProviderConnection from './ProviderConnection.svelte';
 import FieldInsightPage from './FieldInsightPage.svelte';
 import {insightPages,isInsightPage} from './insight-pages.mjs';
 import {standardCrop} from './crops.mjs';
 import FieldCapacity from './FieldCapacity.svelte';
 import CropAdministration from './CropAdministration.svelte';
 import BoundaryMap from './BoundaryMap.svelte';
 import FieldMapReview from './FieldMapReview.svelte';
 import FieldWeather from './FieldWeather.svelte';
 import CropInsights from './CropInsights.svelte';
 import FieldPassport from './FieldPassport.svelte';
 import ObservationTrend from './ObservationTrend.svelte';
 import {normalizeIndex,sensedMap} from './satellite.mjs';
 import './portal.css';
 let {data,form}: {data:any,form?:any}=$props();
 let menu=$state(false),boundary=$state(''),selectedFarm=$state(''),selectedZone=$state(untrack(()=>data.initialZone||'')),selectedDate=$state(''),layer=$state('ndvi'),busy=$state(false);
 const farmerNav=[['overview','Overview'],['farms','My farms'],['satellite','Satellite monitoring'],['weather','Weather'],...insightPages,['analysis','Analysis & reports'],['account','Account & support']];
 const adminNav=[['overview','Operations overview'],['users','Farmers & invitations'],['quota','Hectare allocations'],['requests','Monitoring requests'],['operations','Integration health'],['crops','Crops & analysis']];
 let nav=$derived(data.admin?adminNav:farmerNav);
 let farms=$derived(data.tables.talazo_farms),zones=$derived(data.tables.talazo_zones),monitoring=$derived(data.tables.talazo_monitoring.filter((m:any)=>m.environment===data.environment));
 let insightPage=$derived(isInsightPage(data.section));
 let insightEnabled=$derived(Boolean(data.insightZoneIds?.length));
 let pageZones=$derived(insightPage?zones.filter((z:any)=>data.insightZoneIds?.includes(z.id)):zones);
 let previousField=$state(untrack(()=>data.initialZone||''));
 $effect(()=>{const field=data.initialZone;if(field&&field!==previousField){selectedZone=field;selectedFarm='';previousField=field;}});
 let pageFarms=$derived(insightPage?farms.filter((f:any)=>pageZones.some((z:any)=>z.farm_id===f.id)):farms);
 let effectiveFarm=$derived(pageFarms.some((f:any)=>f.id===selectedFarm)?selectedFarm:'');
 let visibleZones=$derived(effectiveFarm?pageZones.filter((z:any)=>z.farm_id===effectiveFarm):pageZones);
 let zone=$derived(visibleZones.find((z:any)=>z.id===selectedZone)||visibleZones[0]);
 let record=$derived(monitoring.find((m:any)=>m.zone_id===zone?.id));
 let observation=$derived(data.tables.talazo_observations.find((o:any)=>o.monitoring_id===record?.id));
 let products=$derived(observation?.data?.products||{});
 let indices=$derived(products.getAllIndexValues?.value||{});
 let sensed=$derived(sensedMap(products.getSensedDays?.value));
 let dates=$derived(Object.keys(sensed).sort().reverse());
 let date=$derived(dates.includes(selectedDate)?selectedDate:dates[0]);
 let latest=$derived(normalizeIndex(indices.ndvi?.[date]));
 let forecast=$derived(products.getForecastWeather?.value?.normal||products.getForecastWeather?.value||{});
 let weather=$derived(products.getPresentWeather?.value?.current);
 let period=$derived(data.tables.talazo_periods.find((p:any)=>p.period===data.period));
 let allocations=$derived(data.tables.talazo_allocations.filter((a:any)=>a.period===data.period));
 let allocated=$derived(allocations.reduce((n:number,a:any)=>n+Number(a.sqm),0));
 let monitored=$derived(zones.filter((z:any)=>monitoring.some((m:any)=>m.zone_id===z.id&&['registering','uncertain','awaiting','active'].includes(m.status))).reduce((n:number,z:any)=>n+Number(z.area_sqm),0));
 const ha=(sqm:number)=>new Intl.NumberFormat('en',{maximumFractionDigits:4}).format(Number(sqm||0)/10000);
 const dateText=(v:string)=>v&&/^\d{8}$/.test(v)?`${v.slice(6)}/${v.slice(4,6)}/${v.slice(0,4)}`:v?new Date(v).toLocaleString('en-GB',{timeZone:'Africa/Harare'}):'Not yet available';
 const nameOf=(z:any)=>farms.find((f:any)=>f.id===z?.farm_id)?.name||'Farm';
 const statusText=(s:string)=>({requested:'Awaiting Talazo approval',registering:'Registering',uncertain:'Needs reconciliation',awaiting:'Awaiting observations',active:'Monitoring',paused:'Monitoring paused',error:'Needs attention'}[s]||'Not requested');
 let reportKind=$state('image'),reportChoice=$state('');
 let reportRadar=$derived(['image','geotiff'].includes(reportKind)&&['rvi','rsm'].includes(layer));
 let reportDates=$derived(imageDates(products[reportRadar?'getSARDays':'getSensedDays']?.value,reportRadar));
 let reportDate=$derived(reportDates.includes(reportChoice)?reportChoice:reportDates.includes(date)?date:reportDates[0]);
 let crop=$state('');
 let matchedCrop=$derived(standardCrop(crop,data.tables.talazo_crop_catalog));
 const enhanced=feedbackForm({onBusy:value=>busy=value});
 let setupFarm=$state('');
 $effect(()=>{if(form?.savedFarm)setupFarm=form.savedFarm;else if(!setupFarm&&farms.length)setupFarm=farms[0].id;});
 const fieldEnhanced=feedbackForm({onBusy:value=>busy=value,onSuccess:element=>{
  boundary='';crop='';
  for(const name of ['name','sowing','notes']){const input=element.querySelector<HTMLInputElement|HTMLTextAreaElement>(`[name="${name}"]`);if(input){input.value='';input.dispatchEvent(new Event('input',{bubbles:true}));}}
 }});
</script>
<svelte:window onkeydown={e=>{if(e.key==='Escape')menu=false;}}/>
<svelte:head><title>{nav.find(([id])=>id===data.section)?.[1]} · Talazo</title><meta name="robots" content="noindex,nofollow"/></svelte:head>
<a class="skip" href="#portal-content">Skip to content</a>
<div class="p-shell">
 <aside id="portal-navigation" class="p-sidebar" class:open={menu}>
  <button type="button" class="p-menu p-button subtle p-close-menu" aria-label="Close navigation" onclick={()=>menu=false}>Close menu</button>
  <a class="p-logo" href={data.admin?'/admin/overview':'/portal/overview'}><img src="/images/talazo-logo-cropped.png" alt="Talazo Agritech"/></a>
  <p class="p-kicker">{data.admin?'PLATFORM OPERATIONS':'YOUR GROWING SEASON'}</p>
  <nav aria-label="Main navigation">{#each nav as [id,label],i}{#if !data.admin&&id==='health'}<p class="p-nav-group">CROP INTELLIGENCE</p>{/if}{#if !data.admin&&isInsightPage(id)&&!insightEnabled}<span class="p-nav-disabled" role="link" aria-disabled="true" aria-describedby="insight-activation-note"><span aria-hidden="true">{String(i+1).padStart(2,'0')}</span>{label}</span>{:else}<a class:current={data.section===id} aria-current={data.section===id?'page':undefined} href={`/${data.admin?'admin':'portal'}/${id}`} onclick={()=>menu=false}><span aria-hidden="true">{String(i+1).padStart(2,'0')}</span>{label}</a>{/if}{/each}</nav>
  {#if !data.admin&&!insightEnabled}<p id="insight-activation-note" class="p-nav-note">Crop pages unlock when a field has active satellite monitoring.</p>{/if}
  {#if data.isAdmin}<a class="p-switch" href={data.admin?'/portal/overview':'/admin/overview'}>{data.admin?'Open farmer workspace':'Open administration'} ↗</a>{/if}
  <div class="p-sidebar-foot"><span class="p-leaf" aria-hidden="true"></span><strong>Rooted in better decisions.</strong><p>Field intelligence.<br/>A clearer way forward.</p><form method="POST" action="?/signout" use:enhance={enhanced}><button class="p-button subtle">Sign out</button></form></div>
 </aside>
 <div class="p-body">
  <header class="p-topbar"><button class="p-menu p-button subtle" aria-expanded={menu} onclick={()=>menu=!menu}>Menu</button><span>{data.admin?'Talazo administration':data.name}</span><div><span class="p-status">{data.environment==='test'?'Test environment':'Satellite monitoring'}</span><span class="p-avatar">{data.name.slice(0,1).toUpperCase()}</span></div></header>
  <main id="portal-content" class="p-main">
   <div class="p-heading"><div><p class="p-kicker">TALAZO / {data.admin?'ADMINISTRATION':'FARM INTELLIGENCE'}</p><h1>{data.section==='overview'?(data.admin?'The whole picture.':'Your season, in focus.'):nav.find(([id])=>id===data.section)?.[1]}</h1><p>{data.admin?'Support your farmers. Keep every hectare accounted for.':'Understand your fields, follow change, and know where to look next.'}</p></div>{#if !data.admin&&data.section!=='farms'}<a class="p-button" href="/portal/farms">Manage my land <span aria-hidden="true">↗</span></a>{/if}</div>
   {#if data.environment==='test'}<div class="p-test"><strong>Test mode</strong> Provider results are samples, not observations of your farm. Test and live records are kept separate.</div>{/if}
   {#if data.liveRegistrationIssue}<div class="p-test" role="status">The live Farmonaut registration needs administrator reconciliation. Do not submit the field again until the provider confirms its identifier and boundary.</div>{/if}
   {#if form?.message}<div class="p-feedback" role="status">{form.message}</div>{/if}
   {#if form?.invitation}<section class="p-card"><h2>Private activation link</h2><p>Share this single-use link directly with the approved farmer. Treat it as a credential.</p><label class="p-field">Access link<input readonly value={form.invitation} onclick={e=>e.currentTarget.select()}/></label></section>{/if}
   {#if busy}<p role="status" class="p-working">Saving your request…</p>{/if}

   {#if data.admin}
    {#if data.section==='overview'}
     <OperationsDashboard {data}/>
     <ProviderInventory {data} {enhanced} {busy} compact/>
     <div class="p-stats"><article><span>Approved farmers</span><strong>{data.users.filter((u:any)=>u.status!=='suspended').length}</strong><small>Accounts under your care</small></article><article><span>Monthly paid quota</span><strong>{period?ha(period.quota_sqm):'—'} <em>ha</em></strong><small>{data.period.slice(0,7)} · entered by administrator</small></article><article><span>Allocated</span><strong>{ha(allocated)} <em>ha</em></strong><small>{period?ha(period.quota_sqm-allocated)+' ha unallocated':'Set your quota first'}</small></article><article><span>Pending requests</span><strong>{monitoring.filter((m:any)=>m.status==='requested').length}</strong><small>Waiting for your review</small></article></div>
     <div class="p-grid"><a class="p-card p-link-card" href="/admin/quota"><p class="p-kicker">01 / CAPACITY</p><h2>Set the limits. Allocate with confidence. ↗</h2><p>Database checks prevent total allocations exceeding your monthly paid hectares.</p></a><a class="p-card p-link-card" href="/admin/requests"><p class="p-kicker">02 / MONITORING</p><h2>Bring approved land into view. ↗</h2><p>Review field boundaries and reserved area before registering with Farmonaut.</p></a></div>
    {:else if data.section==='users'}
     <section class="p-card"><p class="p-kicker">CONTROLLED ONBOARDING</p><h2>Welcome a farmer to Talazo.</h2><p>The farmer receives a private activation link and chooses their own password. Existing approved farmers can receive a fresh access link here.</p><form method="POST" action="?/invite" use:enhance={enhanced} class="p-form"><label class="p-field">Farmer name<input name="name" required maxlength="120" autocomplete="name"/></label><label class="p-field">Email address<input name="email" required type="email" autocomplete="email"/></label><label class="p-field">Delivery<select name="delivery"><option value="supabase">Send invitation through Supabase email</option><option value="link">Generate a link to share directly</option>{#if data.emailReady}<option value="email">Send invitation email</option>{/if}</select></label><button disabled={busy} class="p-button">Approve farmer & create access link ↗</button></form>{#if !data.emailReady}<p class="p-caption">Supabase sends invitation emails using your Auth email settings. For production, configure a verified SMTP sender and allow this app’s redirect URL. Private links are available if email delivery is unavailable.</p>{/if}</section>
     <section class="p-card"><h2>Farmer register <span class="p-muted">/ {data.users.length}</span></h2><div class="p-table"><table><thead><tr><th>Farmer</th><th>Status</th><th>Access</th></tr></thead><tbody>{#each data.users as u}<tr><td><strong>{u.name}</strong><small>{u.email}</small></td><td><span class="p-pill">{u.status}</span></td><td><form method="POST" action="?/status" use:enhance={enhanced}><input type="hidden" name="user" value={u.user_id}/><input type="hidden" name="status" value={u.status==='suspended'?'active':'suspended'}/><button disabled={busy} class="p-button subtle">{u.status==='suspended'?'Reactivate':'Suspend access'}</button></form></td></tr>{:else}<tr><td colspan="3">No farmers registered yet. Start with an invitation above.</td></tr>{/each}</tbody></table></div></section>
     <section class="p-card"><h2>Set up a farm on a farmer’s behalf</h2><form method="POST" action="?/farm" use:enhance={enhanced} class="p-form"><label class="p-field">Owner<select name="owner" required><option value="">Choose a farmer</option>{#each data.users as u}<option value={u.user_id}>{u.name}</option>{/each}</select></label><label class="p-field">Farm name<input name="name" required maxlength="120"/></label><label class="p-field">District<input name="district" maxlength="120"/></label><button class="p-button" disabled={busy}>Create farm</button></form><p class="p-caption">Use the farmer workspace to add growing areas to farms you manage.</p></section>
    {:else if data.section==='quota'}
     <div class="p-grid"><section class="p-card"><p class="p-kicker">PAID CAPACITY</p><h2>Your monthly hectare quota</h2><p>Enter the hectares covered by your paid subscription. This is your declared allowance, not a provider-verified balance.</p><form method="POST" action="?/quota" use:enhance={enhanced} class="p-form single"><label class="p-field">Paid month<DatePicker name="period" value={data.period.slice(0,7)} mode="month" label="Paid month" required/></label><label class="p-field">Monthly quota (ha)<input type="number" name="hectares" min="0" step="0.0001" value={period?period.quota_sqm/10000:''} required/></label><button class="p-button" disabled={busy}>Save monthly quota</button></form></section><section class="p-card"><p class="p-kicker">FARMER ALLOWANCE</p><h2>Allocate monitored hectares</h2><form method="POST" action="?/allocation" use:enhance={enhanced} class="p-form single"><label class="p-field">Farmer<select name="user" required><option value="">Choose farmer</option>{#each data.users as u}<option value={u.user_id}>{u.name}</option>{/each}</select></label><label class="p-field">Paid month<DatePicker name="period" value={data.period.slice(0,7)} mode="month" label="Paid month" required/></label><label class="p-field">Total allowance for this farmer (ha)<input type="number" name="hectares" min="0" step="0.0001" required/></label><button class="p-button" disabled={busy}>Save allocation</button></form></section></div>
     <section class="p-card"><h2>Allocation ledger</h2><div class="p-table"><table><thead><tr><th>Month</th><th>Farmer</th><th>Allocated hectares</th></tr></thead><tbody>{#each data.tables.talazo_allocations as a}<tr><td>{a.period.slice(0,7)}</td><td>{data.users.find((u:any)=>u.user_id===a.user_id)?.name||'Farmer'}</td><td>{ha(a.sqm)} ha</td></tr>{:else}<tr><td colspan="3">No allocations yet.</td></tr>{/each}</tbody></table></div></section>
    {:else if data.section==='crops'}
     <CropAdministration {data} {enhanced} {busy}/>
    {:else if data.section==='requests'}
     <section class="p-card"><h2>Monitoring requests</h2><p>Registration reserves the farmer’s allocated area. Uncertain registrations retain that reservation to prevent duplicate submissions.</p>{#each monitoring as m}{@const z=zones.find((z:any)=>z.id===m.zone_id)}<article class="p-request"><div><p class="p-kicker">{nameOf(z)} / {ha(z?.area_sqm)} HA</p><h3>{z?.name}</h3><p>{z?.crop_name} · {statusText(m.status)}</p>{#if m.error}<p class="p-error">{m.error}</p>{/if}<FieldMapReview boundary={z?.boundary} label="Review field boundary on Google Maps"/></div><div>{#if ['requested','paused'].includes(m.status)}<form method="POST" action="?/register" use:enhance={enhanced}><input type="hidden" name="monitoring" value={m.id}/><button disabled={busy||!data.providerConfigured} class="p-button">{m.status==='paused'?'Resume monitoring':data.environment==='test'?'Approve sample preview':'Approve & register field'}</button></form>{:else if m.provider_id}<form method="POST" action="?/sync" use:enhance={enhanced}><input type="hidden" name="monitoring" value={m.id}/><button disabled={busy} class="p-button subtle">Refresh observations</button></form>{#if ['active','awaiting'].includes(m.status)}{#if data.environment==='live'}<form method="POST" action="?/details" use:enhance={enhanced}><input type="hidden" name="monitoring" value={m.id}/><button disabled={busy} class="p-button subtle">Sync field details to Farmonaut</button></form>{/if}<form method="POST" action="?/pause" use:enhance={enhanced}><input type="hidden" name="monitoring" value={m.id}/><button disabled={busy} class="p-button subtle">Pause monitoring</button></form>{/if}{/if}<small>Last sync: {dateText(m.last_sync)}</small></div></article>{:else}<div class="p-empty compact"><h3>No requests to review.</h3><p>Requests appear after a farmer maps their growing area.</p></div>{/each}</section>
    {:else}
     <ProviderInventory {data} {enhanced} {busy}/>
     <JobHealth jobs={data.jobs}/>
     <FieldChanges {data} {enhanced} {busy}/>
     <HistoryRequests {data} {enhanced} {busy}/>
     {#if data.liveRegistrationIssue}<section class="p-card"><p class="p-kicker">LIVE CONNECTION / RECONCILIATION REQUIRED</p><h2>Verify the first registration before retrying.</h2><p>The provider did not return a verified registration. Open your Farmonaut account and check whether the submitted field already exists. If it does, enter its ID below. Talazo will verify the boundary before saving the mapping.</p><a class="p-button subtle" href="https://sat.farmonaut.com/" target="_blank" rel="noopener noreferrer">Open Farmonaut account ↗</a>{#each data.tables.talazo_monitoring.filter((m:any)=>m.environment==='live'&&m.status==='uncertain') as m}{@const z=zones.find((z:any)=>z.id===m.zone_id)}<form method="POST" action="?/discover" use:enhance={enhanced}><input type="hidden" name="monitoring" value={m.id}/><button class="p-button subtle" disabled={busy}>Find &amp; verify existing field</button></form><form method="POST" action="?/reconcile" use:enhance={enhanced} class="p-form"><input type="hidden" name="monitoring" value={m.id}/><label class="p-field">{nameOf(z)} / {z?.name} · Farmonaut field ID<input name="provider_id" required maxlength="120" autocomplete="off"/></label><button class="p-button" disabled={busy}>Verify existing live field</button></form><p class="p-caption">{m.error}</p>{/each}</section>{/if}<section class="p-card"><h2>Integration health</h2><dl class="p-facts"><div><dt>Provider</dt><dd>Farmonaut</dd></div><div><dt>API key</dt><dd>{data.providerConfigured?'Configured on server':'Missing'}</dd></div><div><dt>Environment</dt><dd>{data.environment}</dd></div><div><dt>Google Maps</dt><dd>{data.mapsConfigured?'Browser key configured':'Add PUBLIC_GOOGLE_MAPS_API_KEY'}</dd></div><div><dt>Monitored area committed</dt><dd>{ha(monitored)} ha</dd></div></dl><form method="POST" action="?/connection" use:enhance={enhanced}><button class="p-button subtle" disabled={busy||!data.providerConfigured}>Check production connection</button></form>
{#if form?.connectionChecks}<div class="p-feedback" role="status"><p>Checked: {dateText(form.connectionCheckedAt)}</p>{#each form.connectionChecks as check}<p><strong>{check.endpoint}: {check.ok?'Responding':'Needs attention'}</strong><br/>{check.message}</p>{/each}</div>{/if}
<p>Approved fields are registered in your live Farmonaut account. Pausing and resuming monitoring also updates Farmonaut. Farmer accounts, approvals, hectare allocations and field activity records are managed in Talazo.</p><p>Scheduled synchronization requires the protected worker endpoint and a hosting scheduler. Account usage alone does not establish working field imagery.</p></section><section class="p-card"><h2>Recent activity</h2>{#each data.events as e}<div class="p-activity"><span>{e.action.replaceAll('_',' ')}</span><small>{dateText(e.created_at)}</small></div>{:else}<p>No activity recorded yet.</p>{/each}</section>
    {/if}
   {:else}
    {#if data.section==='overview'}
     <CropDashboard {data}/>
    {:else if data.section==='farms'}
     <section class="p-card"><p class="p-kicker">YOUR LAND / THREE SIMPLE STEPS</p><h2>A farm can contain many fields.</h2><ol class="p-checklist"><li class:done={farms.length}>Create your farm<small>Record its name and district.</small></li><li class:done={zones.length}>Map each field<small>Draw its boundary or enter its corner coordinates. Add crop and planting details.</small></li><li class:done={monitoring.length}>Request monitoring<small>Talazo approves each field against your hectare allocation.</small></li></ol></section><section class="p-card"><p class="p-kicker">01 / FARM DETAILS</p><h2>{farms.length?'Add another farm.':'Let’s put your farm on the map.'}</h2><form method="POST" action="?/farm" use:enhance={enhanced} class="p-form"><label class="p-field">Farm name<input name="name" required maxlength="120" placeholder="e.g. Mupfuti Farm"/></label><label class="p-field">District<input name="district" maxlength="120" placeholder="e.g. Goromonzi"/></label>{#if data.isAdmin}<label class="p-field">Farm owner<select name="owner" required><option value={data.userId}>My own farm (administrator)</option>{#each data.users as u}<option value={u.user_id}>{u.name}</option>{/each}</select></label>{/if}<button class="p-button" disabled={busy}>Save farm ↗</button></form></section>
     {#if farms.length}<section class="p-card"><p class="p-kicker">02 / FIELDS & ZONES</p><h2>Add a field to your farm.</h2><p>Draw a boundary around one cultivated area. Separate areas can have different crops, soil conditions and planting dates.</p><form method="POST" action="?/zone" use:enhance={fieldEnhanced}><div class="p-form"><label class="p-field">Farm<select name="farm" required bind:value={setupFarm}>{#each farms as f}<option value={f.id}>{f.name}</option>{/each}</select></label><label class="p-field">Growing area name<input name="name" required maxlength="120" placeholder="e.g. North field"/></label><label class="p-field">Crop name<small aria-live="polite">{crop.trim()?(matchedCrop.review?'Saved as entered; Talazo will classify it for reporting.':'Standard reporting crop: '+matchedCrop.name):'Type the crop you grow. We standardize its name for reporting.'}</small><input name="crop_name" bind:value={crop} required maxlength="120" placeholder="e.g. Maize, soya beans, groundnuts"/></label><label class="p-field">Actual planting date <small>Optional</small><DatePicker name="sowing" max={todayISO()} label="Actual planting date"/></label></div><BoundaryMap bind:value={boundary}/><input type="hidden" name="boundary" value={boundary}/><FieldCapacity {boundary} farm={setupFarm} {farms} {zones} {allocations} period={data.period}/><details><summary>Enter or review boundary coordinates</summary><label class="p-field">GeoJSON Polygon (longitude, latitude)<textarea bind:value={boundary} rows="5" required placeholder={JSON.stringify({type:'Polygon',coordinates:[[[31,-17],[31.01,-17],[31.01,-17.01],[31,-17]]]})}></textarea></label></details><label class="p-field">Soil, irrigation, drainage & field notes<textarea name="notes" rows="3" maxlength="2000" placeholder="What is distinctive about this growing area?"></textarea></label><button class="p-button" disabled={busy||!boundary}>Save field ↗</button><p class="p-caption">The server validates the boundary and calculates hectares before saving. Saving does not start paid monitoring. Add another field using this form; each field keeps its own crop, boundary and monitoring record.</p></form></section>{/if}
     <FieldChanges {data} {enhanced} {busy}/><section class="p-card"><h2>Your growing areas</h2>{#each zones as z}{@const m=monitoring.find((m:any)=>m.zone_id===z.id)}<article class="p-request"><div><p class="p-kicker">{nameOf(z)} / {ha(z.area_sqm)} HA</p><h3>{z.name}</h3><p>{z.crop_name} · {z.sowing_date||'Planting date not recorded'}</p><p class="p-caption">{z.characteristics}</p><FieldMapReview boundary={z.boundary}/></div><div>{#if m}<span class="p-pill">{statusText(m.status)}</span>{:else}<form method="POST" action="?/request" use:enhance={enhanced}><input type="hidden" name="zone" value={z.id}/><button class="p-button subtle" disabled={busy}>Request monitoring</button></form>{/if}</div></article>{:else}<div class="p-empty compact"><h3>No growing areas yet.</h3><p>Save a farm, then draw its first field above.</p></div>{/each}</section>
    {:else if ['satellite','weather','analysis'].includes(data.section)||insightPage}
     {#if record&&['active','awaiting'].includes(record.status)&&data.section!=='weather'}{#key record.id}<ProviderConnection {record}/>{/key}{/if}
     {#if pageZones.length}<section class="p-filter"><label class="p-field">Farm<select bind:value={selectedFarm}><option value="">All my farms</option>{#each pageFarms as f}<option value={f.id}>{f.name}</option>{/each}</select></label><label class="p-field">Field<select value={zone?.id||''} onchange={e=>{selectedZone=e.currentTarget.value;selectedDate='';}}>{#if !visibleZones.length}<option value="">No fields in this farm</option>{/if}{#each visibleZones as z}<option value={z.id}>{z.name} · {nameOf(z)}</option>{/each}</select></label>{#if data.section!=='weather'}<label class="p-field">Available observation<select bind:value={selectedDate} disabled={!dates.length}>{#if !dates.length}<option value="">Awaiting observations</option>{:else}<option value="">Latest · {dateText(dates[0])}</option>{#each dates as d}<option value={d}>{dateText(d)}</option>{/each}{/if}</select></label><span class="p-pill">{statusText(record?.status)}</span>{/if}</section>{/if}
     {#if data.section==='weather'&&zone}<FieldMapReview boundary={zone.boundary} label="View weather location on Google Maps"/><FieldWeather {zone} cached={data.tables.talazo_weather.find((w:any)=>w.zone_id===zone.id&&w.environment===data.environment)} {products} {enhanced} {busy}/>
     {:else if insightPage}
      {#if !insightEnabled}<section class="p-card p-empty"><p class="p-kicker">CROP INTELLIGENCE / NOT ACTIVE YET</p><h2>Activate a field to open this page.</h2><p>Save a farm and field, request satellite monitoring, then wait for Talazo approval and the first observations. This page becomes available automatically when monitoring is active.</p><a class="p-button" href="/portal/farms">Review my farms</a></section>
      {:else if !zone||!record||!observation}<section class="p-card p-empty"><h2>Your field data is getting ready.</h2><p>Select an active field. Its dated information will appear after observations have synchronized.</p><a class="p-button subtle" href="/portal/satellite">View monitoring status</a></section>
      {:else}{#key record.id+date+data.section}<FieldInsightPage section={data.section} {zone} farm={farms.find((f:any)=>f.id===zone.farm_id)} {record} {products} {date} {enhanced} {busy} onObservationChange={(value:string)=>selectedDate=value}/>{/key}{/if}
     {:else if record?.status==='awaiting'&&record.provider_id&&!dates.length}<section class="p-card p-empty"><div class="p-orbit" aria-hidden="true">◎</div><p class="p-kicker">FIELD CONNECTED / AWAITING SATELLITE DATA</p><h2>Your field is registered with Farmonaut.</h2><p>{zone?.name} is connected. Farmonaut has not returned an available optical observation yet. Talazo checks automatically while this page is open; crop maps, advice and dated reports become available after observations synchronize.</p><dl class="p-facts"><div><dt>Farmonaut field ID</dt><dd>{record.provider_id}</dd></div><div><dt>Last check</dt><dd>{dateText(record.last_sync)}</dd></div></dl><a class="p-button" href="/portal/weather">View field weather ↗</a><p class="p-caption">You do not need to register this field again.</p></section>
     {:else if !record||!observation}<section class="p-card p-empty"><div class="p-orbit" aria-hidden="true">◎</div><p class="p-kicker">YOUR NEXT CHAPTER</p><h2>{record?'Your field is getting ready.':'Bring your fields into view.'}</h2><p>{record?`Current status: ${statusText(record.status)}. Observations will appear here after registration and synchronization.`:'Map your growing areas and request monitoring to see satellite imagery, weather and reports.'}</p><a class="p-button" href="/portal/farms">Review my growing areas ↗</a></section>
     {:else}
      <div class="p-stats"><article><span>Vegetation / NDVI</span><strong>{latest===null?'—':latest.toFixed(2)}</strong><small>{date?dateText(date):'No usable date'}</small></article><article><span>Moisture index / NDMI</span><strong>{normalizeIndex(indices.ndmi?.[date])?.toFixed(2)??'—'}</strong><small>Satellite index · not soil moisture %</small></article><article><span>Growing area</span><strong>{ha(zone.area_sqm)} <em>ha</em></strong><small>{zone.crop_name}</small></article><article><span>Observation context</span><strong class="p-small-stat">{(sensed[date] as any)?.isCloudy?'Cloud affected':'Review quality'}</strong><small>Last sync {dateText(record.last_sync)}</small></article></div>
      {#if data.section==='satellite'}{#key record.id+date}<FieldInsightPage section="satellite" {zone} farm={farms.find((f:any)=>f.id===zone.farm_id)} {record} {products} {date} {enhanced} {busy} onObservationChange={(value:string)=>selectedDate=value}/>{/key}{/if}
      {#if data.section==='analysis'}<CropInsights {record} {date} product={products.askJeevnAPI} {enhanced} {busy}/>{/if}
      <div class="p-grid"><section class="p-card"><p class="p-kicker">{data.section==='analysis'?'ANALYSIS / SEASONAL CHANGE':'SATELLITE / VEGETATION HISTORY'}</p><h2>See how your field changes.</h2><ObservationTrend series={indices.ndvi||{}}/><p class="p-caption">Provider indices use a clipped scale. A value alone does not diagnose a disease or determine an irrigation requirement.</p></section><section class="p-card"><p class="p-kicker">{data.section==='analysis'?'REPORT LIBRARY':'IMAGE EXPLORER'}</p><h2>{data.section==='analysis'?'Your field, ready to review.':'A different view of your land.'}</h2><p>{data.section==='analysis'?'Generate a dated field report, advisory report or georeferenced export.':'Choose a layer and an available observation date. The provider returns an image for the selected field.'}</p><form method="POST" action="?/report" use:enhance={enhanced} class="p-form single"><input type="hidden" name="monitoring" value={record.id}/><input type="hidden" name="date" value={reportDate||''}/><label class="p-field">Report observation<select bind:value={reportChoice} disabled={!reportDates.length}><option value="">Latest available / {dateText(reportDate)}</option>{#each reportDates as d}<option value={d}>{dateText(d)}</option>{/each}</select></label><label class="p-field">Layer<select name="layer" bind:value={layer}><option value="ndvi">Vegetation / NDVI</option><option value="tci">True colour</option><option value="evi">Enhanced vegetation / EVI</option><option value="ndmi">Moisture index / NDMI</option><option value="ndwi">Water index / NDWI</option><option value="ndre">Red edge / NDRE</option><option value="savi">Soil-adjusted vegetation / SAVI</option><option value="rvi">Radar vegetation / RVI</option><option value="rsm">Radar moisture / RSM</option><option value="soc">Organic carbon / SOC</option></select></label><label class="p-field">Output<select name="kind" bind:value={reportKind}><option value="image">Satellite image</option><option value="pdf">PDF field report</option><option value="advisory">Interactive advisory report</option><option value="recommendations">Structured AI advisory</option><option value="geotiff">GeoTIFF download</option></select></label><button class="p-button" disabled={busy||!reportDate}>Generate output ↗</button></form><p class="p-caption">Outputs are supplied by Farmonaut. Some layers may not be available for every date.</p></section></div>
      {#if form?.asset && form.assetMonitoring===record?.id && form.assetDate===reportDate}<section class="p-card"><h2>{data.environment==='test'?'Sample output':'Your output is ready'}</h2>{#if form.assetKind==='image'}<img class="p-result-image" src={form.asset} alt="Provider satellite output for the selected layer and date" referrerpolicy="no-referrer"/>{/if}<a class="p-button" href={form.asset} target="_blank" rel="noopener noreferrer">Open {form.assetKind==='image'?'image':'report or download'} ↗</a></section>{/if}
      {#if data.section==='analysis'}<div class="p-grid"><section class="p-card"><p class="p-kicker">OBSERVATION DETAIL</p><h2>Available index measurements</h2><p class="p-caption">Values for the selected date. Missing values are left unavailable, not substituted from another date.</p><dl class="p-facts">{#each Object.entries(indices) as [key,values]}<div><dt>{key.toUpperCase()}</dt><dd>{normalizeIndex((values as any)?.[date])?.toFixed(2)??'Unavailable'}</dd></div>{/each}</dl></section><section class="p-card"><p class="p-kicker">WHERE TO INSPECT</p><h2>Provider inspection flags</h2><p>These references describe Farmonaut’s nine-cell inspection grid. They are separate from your named farm zones.</p><dl class="p-facts"><div><dt>Crop review grid cells</dt><dd>{((sensed[date] as any)?.cropRedZones||[]).join(', ')||'No flags returned'}</dd></div><div><dt>Water-stress review grid cells</dt><dd>{((sensed[date] as any)?.irrigationRedZones||[]).join(', ')||'No flags returned'}</dd></div></dl><p class="p-caption">A flag is a reason to inspect the field, not a confirmed diagnosis.</p></section></div>{/if}
      {#if form?.recommendations && form.assetMonitoring===record?.id && form.assetDate===date}<section class="p-card"><p class="p-kicker">PROVIDER-GENERATED ADVISORY</p><h2>Review with your field conditions.</h2><p>These are generated recommendations. Confirm crop stage, observations and local agronomic requirements before acting.</p>{#each Object.entries(form.recommendations) as [topic,value]}<details class="p-advisory"><summary>{topic.replaceAll('_',' ')}</summary><pre>{typeof value==='string'?value:JSON.stringify(value,null,2)}</pre></details>{/each}</section>{/if}
      {#if Object.keys(observation.data.errors||{}).length}<div class="p-test">Some products were unavailable at the last sync. Available results are retained with their own retrieval dates.</div>{/if}
     {/if}
     {#if data.section==='analysis'&&zone}<FieldPassport {zone} farm={farms.find((f:any)=>f.id===zone.farm_id)} activities={data.tables.talazo_field_activities} {enhanced} {busy}/>{/if}
    {:else}<section class="p-card"><p class="p-kicker">YOUR TALAZO ACCOUNT</p><h2>{data.name}</h2><dl class="p-facts"><div><dt>Access</dt><dd>Approved by Talazo</dd></div><div><dt>Current monthly allocation</dt><dd>{ha(allocated)} ha</dd></div><div><dt>Support</dt><dd>Contact the Talazo team who invited you</dd></div></dl><p>Need help with a boundary, a new access link, or more monitored hectares? Your administrator can review your account.</p><a class="p-button subtle" href="/activate">Change password</a></section>{/if}
   {/if}
   {#if !data.admin&&['overview','account'].includes(data.section)}<AlertCenter {data} {enhanced} {busy}/>{/if}
   {#if !data.admin&&data.section==='analysis'}{#if record}<section class="p-card"><h2>Export your field observations</h2><p>Download dated index readings with provider attribution and retrieval times. This is an observation record, not a compliance certificate.</p><a class="p-button subtle" href={'/api/satellite/export?monitoring='+record.id}>Download observations CSV</a></section>{/if}<HistoryRequests {data} {enhanced} {busy}/>{/if}
   <footer class="p-footer"><span>Talazo Agritech · Better decisions. Stronger roots.</span><span>Satellite data provided by Farmonaut</span></footer>
  </main>
 </div>
</div>
